head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > E > oneditenter]<br/>Textarea 컴포넌트에서 Tab 키 또는 Enter 키를 누를 때 발생합니다.<br/>Enter 키에 의한 포커스 이동은 nextTabByEnter 속성이 true 인 경우에만 동작합니다.",
    "validation" : [
        "Tab 키 입력 시 oneditenter 이벤트가 발생합니다.",
        "이벤트 객체 e (KeyboardEvent) 가 핸들러에 전달됩니다.",
        "반환값이 true(default) 인 경우 Tab 키 입력 시 nextTabID 속성에 맞게 포커스가 이동합니다.",
        "반환값이 false 인 경우 Tab 키 입력 시 nextTabID 속성이 무시되고 일반 포커스 이동 규칙에 따라 이동합니다.",
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 startcomp 있으면 삭제
    if (typeof startcomp !== 'undefined') {
        startcomp.remove();
    }

    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 기존 button2 있으면 삭제
    if (typeof button2 !== 'undefined') {
        button2.remove();
    }

    // 기존 input2 있으면 삭제
    if (typeof input2 !== 'undefined') {
        input2.remove();
    }

    // 조건 설정 (target - textarea, nextTabID 로 button2 지정, 중간 input2 건너뜀)
    let properties = {
        tabIndex: 2,
        nextTabID: "button2",
    };

    let cList = $c.gcm.createCList(properties);

    // 조건 설정 (input2 - tabIndex 순서상 중간 컴포넌트, return false 시 여기로 이동)
    let properties_input = {
        tabIndex: 3,
    };

    let cList_input = $c.gcm.createCList(properties_input);

    // 조건 설정 (button2 - nextTabID 대상, tabIndex 순서상 마지막)
    let properties_button = {
        tabIndex: 4,
    };

    let cList_button = $c.gcm.createCList(properties_button);

    // startcomp input 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strStartComp = '<xf:input ' + strNameSpace + ' tabIndex="1" initValue="start" style="width:144px; height:21px;"></xf:input>';

    scwin.startcomp = await $p.dynamicCreate(
        "startcomp",
        "input",
        strStartComp,
        grp_comp
    );

    // nextTabID 매칭을 위해 대상 컴포넌트(button2)를 target1 생성 전에 먼저 생성. input → button 순서

    // input2 (return false 시 이동 대상) 생성
    $c.gcm.createBasicInput(cList_input, 'ev:onfocus="scwin.input2_onfocus"', "input2");

    // button2 (nextTabID 대상) 생성
    $c.gcm.createBasicButton(cList_button, 'ev:onfocus="scwin.button2_onfocus"', "button2");

    // target1 (textarea) — nextTabID 대상(input2) 생성 후 마지막에 생성해야 nextTabID 매칭됨
    $c.gcm.createBasicTextArea(cList, 'ev:onfocus="scwin.target1_onfocus" ev:onblur="scwin.target1_onblur" ev:oneditenter="scwin.target1_oneditenter"');

    target1.setValue("target");
    input2.setValue("input2");

    // target1(textarea) display='block' 으로 노출 (nextTabID 샘플 패턴)
    scwin.changeDisplay();
}



scwin.changeDisplay = function() {
    let elements = document.querySelectorAll('[id*="target1"]');
    elements.forEach(function(element) {
        element.style.display = 'block';
    });
}



scwin.target1_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onfocus 이벤트 발생=====");
}



scwin.target1_onblur = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onblur 이벤트 발생=====");
}



scwin.target1_oneditenter = function (e) {
    let retVal = (con_return.getText() === "false") ? false : true;
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_oneditenter 호출됨 (return: " + retVal + ")=====");
    wf_body_bottom.getObj("scwin").setReturnValue("e : " + e);
    return retVal;
}



scwin.button2_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====button2_onfocus 이벤트 발생=====");
}



scwin.input2_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====input2_onfocus 이벤트 발생=====");
}
